<?php
declare(strict_types=1);

require dirname(__DIR__) . '/_init.php';
adiwira_require_permission($pdo, 'plugin.study-interest.config.manage', false);

$versionId = filter_var($_GET['version_id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if ($versionId === false || $versionId === null) { http_response_code(404); echo study_interest_h(__('Assessment draft not found.')); return; }
$statement = $pdo->prepare('SELECT v.*,t.code AS test_code,t.title AS test_title,t.description AS test_description FROM study_interest_test_versions v JOIN study_interest_tests t ON t.id=v.test_id WHERE v.id=? LIMIT 1');
$statement->execute([(int)$versionId]);
$version = $statement->fetch(PDO::FETCH_ASSOC);
if (!is_array($version) || (string)$version['status'] !== 'draft') { http_response_code(404); echo study_interest_h(__('Only a draft assessment can be edited.')); return; }
$configuration = json_decode((string)$version['configuration_json'], true, 512, JSON_THROW_ON_ERROR);
if (!is_array($configuration) || !hash_equals((string)$version['configuration_hash'], hash('sha256', study_interest_configuration_json($configuration)))) throw new RuntimeException('Assessment configuration integrity check failed.');
$generic = (int)($configuration['schema_version'] ?? 1) >= 2;
$resultTextLabels = [
    'score_name' => __('Score name'), 'no_dominant_title' => __('Open-profile title'), 'no_dominant_body' => __('Open-profile message'),
    'multidisciplinary' => __('Multidisciplinary message'), 'very_clear' => __('Very clear profile message'), 'fairly_clear' => __('Fairly clear profile message'),
    'open_profile' => __('Open profile message'), 'professional_pathway' => __('Professional pathway heading'), 'professional_pathway_body' => __('Professional pathway message'),
    'disclaimer' => __('Result disclaimer'), 'hero_kicker' => __('Result hero kicker'), 'hero_title' => __('Result hero title'),
    'directions_kicker' => __('Directions kicker'), 'directions_title' => __('Directions title'), 'directions_body' => __('Directions introduction'),
    'dimensions_kicker' => __('Dimensions kicker'), 'dimensions_title' => __('Dimensions title'), 'dimensions_body' => __('Dimensions introduction'),
    'interpretation_kicker' => __('Interpretation kicker'), 'interpretation_title' => __('Interpretation title'), 'next_steps_kicker' => __('Next steps kicker'),
    'next_steps_title' => __('Next steps title'), 'next_steps_body' => __('Next steps message'), 'start_over_label' => __('Start-over button label'),
];
$resultTextFields = $generic ? study_interest_generic_result_text_keys() : [
    'score_name' => 255, 'no_dominant_title' => 255, 'no_dominant_body' => 2000, 'multidisciplinary' => 2000,
    'biomedical_biotechnology_overlap' => 2000, 'midwifery_overlap' => 2000, 'professional_pathway' => 255,
    'professional_pathway_body' => 2000, 'disclaimer' => 2000,
];
$publicCopyLabels = [
    'landing_kicker' => __('Landing kicker'), 'question_count_suffix' => __('Question-count suffix'), 'duration_prefix' => __('Duration prefix'),
    'duration_suffix' => __('Duration suffix'), 'feature_one_title' => __('Feature one title'), 'feature_one_body' => __('Feature one text'),
    'feature_two_title' => __('Feature two title'), 'feature_two_body' => __('Feature two text'), 'feature_three_title' => __('Feature three title'),
    'feature_three_body' => __('Feature three text'), 'progress_label' => __('Progress label'), 'back_label' => __('Back button'),
    'next_label' => __('Next button'), 'complete_label' => __('Complete button'), 'ready_label' => __('Ready state'), 'saving_label' => __('Saving state'),
    'saved_label' => __('Saved state'), 'save_error' => __('Save error'), 'preparing_label' => __('Preparing state'), 'start_label' => __('Start button'),
];
$intakeCopyLabels = ['heading' => __('Intake heading'), 'introduction' => __('Intake introduction'), 'privacy_body' => __('Privacy message'), 'assessment_consent_label' => __('Assessment consent label'), 'contact_heading' => __('Contact heading'), 'contact_introduction' => __('Contact introduction'), 'contact_consent_label' => __('Contact consent label')];
?>
